-- GATE OS - DRE historica estruturada 2022-2025
-- Data: 2026-06-15
-- Fonte: gate_dre_historical_2022_2025_long_for_database.csv
-- Carga idempotente: 3.608 registros esperados.

create table if not exists public.dre_historical_values (
  id uuid primary key default gen_random_uuid(),
  source_sheet text not null,
  line_order integer not null,
  excel_row integer,
  section text,
  line_name text not null,
  row_type text,
  year integer not null,
  month integer not null check (month between 1 and 12),
  competency text not null,
  value numeric default 0,
  excel_col text,
  formula text,
  created_at timestamptz default now()
);

alter table public.dre_historical_values add column if not exists source_sheet text;
alter table public.dre_historical_values add column if not exists line_order integer;
alter table public.dre_historical_values add column if not exists excel_row integer;
alter table public.dre_historical_values add column if not exists row_type text;
alter table public.dre_historical_values add column if not exists excel_col text;
alter table public.dre_historical_values add column if not exists formula text;

create unique index if not exists ux_dre_historical_values_sheet_order_competency
  on public.dre_historical_values (source_sheet, line_order, competency);

create index if not exists idx_dre_historical_values_year_month
  on public.dre_historical_values (year, month);

create index if not exists idx_dre_historical_values_year_order
  on public.dre_historical_values (year, line_order);

on conflict (source_sheet, line_order, competency) do update set
  excel_row = excluded.excel_row,
  section = excluded.section,
  line_name = excluded.line_name,
  row_type = excluded.row_type,
  year = excluded.year,
  month = excluded.month,
  value = excluded.value,
  excel_col = excluded.excel_col,
  formula = excluded.formula;

select count(*) as dre_historical_values_rows from public.dre_historical_values;
select year, count(*) from public.dre_historical_values group by year order by year;
